スクは必ずどこかのユーザーに属する","  belongs_to :user","","  # 1 つのタスクは複数の集中セッションを持てる","  # dependent: :destroy = タスクを消したら、そのタスクの記録も一緒に消す","  # （これをしないと「消えたタスクの記録」が残ってカレンダーでエラーになる）","  has_many :focus_sessions, dependent: :destroy","","  # 1 つのタスクは複数のサブタスクを持てる","  has_many :subtasks, dependent: :destroy","","  # 子タスク（AIに分解で生成された小タスク）","  # 親タスクを消したら子タスクも一緒に消す","  has_many :child_tasks, class_name: 'Task', foreign_key: 'parent_task_id', dependent: :destroy","","  # 親タスク（子タスクの場合にセットされる）","  belongs_to :parent_task, class_name: 'Task', optional: true","","  # AI分解のログ","  has_many :ai_decompose_logs, dependent: :destroy","","  # 使用できる色の一覧（Tailwindのカラー名）","  COLORS = %w[sky violet rose amber emerald orange].freeze","","  # 子タスクが使う実際の色（親がいれば親の色を使う）","  def effective_color","    parent_task ? parent_task.color : color","  end","end","","# ============================================","# AiDecomposeLog モデル","# AIに分解した際の会話ログを保存する","# ============================================","class AiDecomposeLog < ActiveRecord::Base","  belongs_to :task","  belongs_to :user","end","","# ============================================","# FocusSession モデル","# ユーザーがタスクに集中した記録を管理する","# ============================================","class FocusSession < ActiveRecord::Base","  # 集中セッションは必ずどこかのユーザーに属する","  belongs_to :user","","  # 集中セッションは必ずどこかのタスクに属する","  belongs_to :task","end","","# ============================================","# Subtask モデル","# タスクをさらに細かく分けたサブタスクを管理する","# ============================================","class Subtask < ActiveRecord::Base","  # サブタスクは必ずどこかのタスクに属する","  belongs_to :task","end",""],"id":3},{"start":{"row":0,"column":0},"end":{"row":56,"column":3},"action":"insert","lines":["require 'bundler/setup'","Bundler.require","","# 本番（Render）と開発（Cloud9）でデータベース接続を分岐","if ENV['DATABASE_URL']","  ActiveRecord::Base.establish_connection(ENV['DATABASE_URL'])","else","  ActiveRecord::Base.establish_connection(","    adapter: 'sqlite3',","    database: 'db/development.sqlite3'","  )","end","",